import{_ as a,o as n,c as r,ag as e}from"./chunks/framework.OsDJF_Ea.js";const b=JSON.parse('{"title":"재무 모듈 (기관관리자)","description":"","frontmatter":{},"headers":[],"relativePath":"04-org-admin-guide/modules-finance.md","filePath":"04-org-admin-guide/modules-finance.md","lastUpdated":1780579853000}'),d={name:"04-org-admin-guide/modules-finance.md"};function s(l,t,o,i,h,p){return n(),r("div",null,[...t[0]||(t[0]=[e(`<h1 id="재무-모듈-기관관리자" tabindex="-1">재무 모듈 (기관관리자) <a class="header-anchor" href="#재무-모듈-기관관리자" aria-label="Permalink to &quot;재무 모듈 (기관관리자)&quot;">​</a></h1><p>기관 구성원이 매출 청구 / 입금 매칭 / 세금계산서 / 경비 / 계약 / 정산 보고서를 다룰 수 있도록 재무관리 모듈을 활성화합니다.</p><blockquote><p><strong>외부 연동은 자가 등록</strong>: 팝빌 (세금계산서 + 입금조회) / 아임웹 (주문 수집) 자격증명은 본 모듈 활성 후 기관관리자가 직접 화면에서 등록 — 시스템관리자 개입 불필요.</p></blockquote><hr><h2 id="_1-사전-조건" tabindex="-1">1. 사전 조건 <a class="header-anchor" href="#_1-사전-조건" aria-label="Permalink to &quot;1. 사전 조건&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>필수 / 권장</th><th>비고</th></tr></thead><tbody><tr><td>(없음 — 단독 활성 가능)</td><td>—</td><td>재무 모듈 단독으로도 동작</td></tr><tr><td><strong>팝빌 파트너 회원</strong></td><td>권장</td><td>세금계산서 자동 발행 / 입금 자동 수집</td></tr><tr><td><strong>아임웹 OAuth 자격증명</strong></td><td>선택</td><td>아임웹 주문 → billing_item 자동 매핑</td></tr><tr><td><strong>CRM 모듈</strong> 활성</td><td>선택</td><td>견적 → 계약 승격 흐름</td></tr></tbody></table><hr><h2 id="_2-모듈-활성화" tabindex="-1">2. 모듈 활성화 <a class="header-anchor" href="#_2-모듈-활성화" aria-label="Permalink to &quot;2. 모듈 활성화&quot;">​</a></h2><p>좌측 사이드바 → <strong>관리자 → 모듈 관리</strong> (<code>/app/admin/modules</code>) → <strong>&quot;재무관리&quot;</strong> 카드 토글 ON.</p><p>활성화 직후 좌측 사이드바에 <strong>재무관리</strong> 메뉴가 추가됩니다.</p><hr><h2 id="_3-메뉴-노출-정책-m9-a-m9-b" tabindex="-1">3. 메뉴 노출 정책 (M9-A / M9-B) <a class="header-anchor" href="#_3-메뉴-노출-정책-m9-a-m9-b" aria-label="Permalink to &quot;3. 메뉴 노출 정책 (M9-A / M9-B)&quot;">​</a></h2><p>재무관리는 하위 화면이 많아 사용 범위에 맞춰 메뉴를 정리할 수 있습니다.</p><h3 id="_3-1-메뉴-그룹-m9-a" tabindex="-1">3.1 메뉴 그룹 (M9-A) <a class="header-anchor" href="#_3-1-메뉴-그룹-m9-a" aria-label="Permalink to &quot;3.1 메뉴 그룹 (M9-A)&quot;">​</a></h3><p>좌측 메뉴는 다음 그룹으로 구분:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>재무관리</span></span>
<span class="line"><span>├── 매출</span></span>
<span class="line"><span>│   ├── 매출 대장</span></span>
<span class="line"><span>│   ├── 청구</span></span>
<span class="line"><span>│   ├── 입금 매칭</span></span>
<span class="line"><span>│   └── 세금계산서</span></span>
<span class="line"><span>├── 매입</span></span>
<span class="line"><span>│   ├── 경비</span></span>
<span class="line"><span>│   └── 영수증</span></span>
<span class="line"><span>├── 계약</span></span>
<span class="line"><span>└── 보고서</span></span>
<span class="line"><span>    └── 월별 정산</span></span></code></pre></div><h3 id="_3-2-그룹-개별-메뉴-토글-m9-b" tabindex="-1">3.2 그룹 / 개별 메뉴 토글 (M9-B) <a class="header-anchor" href="#_3-2-그룹-개별-메뉴-토글-m9-b" aria-label="Permalink to &quot;3.2 그룹 / 개별 메뉴 토글 (M9-B)&quot;">​</a></h3><p>재무 모듈 카드의 <strong>[설정]</strong> 패널 → <strong>메뉴 표시</strong> 탭:</p><table tabindex="0"><thead><tr><th>토글</th><th>효과</th></tr></thead><tbody><tr><td><strong>그룹 단위 ON/OFF</strong></td><td>예: &quot;매입&quot; 그룹 OFF → 경비 / 영수증 메뉴 한 번에 숨김</td></tr><tr><td><strong>개별 메뉴 ON/OFF</strong></td><td>예: 영수증 메뉴만 숨기고 경비는 유지</td></tr></tbody></table><p>→ 기관의 사용 범위 (예: 매출만 / 매입만 / 둘 다) 에 맞게 정리.</p><hr><h2 id="_4-외부-연동-팝빌-·-아임웹" tabindex="-1">4. 외부 연동 (팝빌 · 아임웹) <a class="header-anchor" href="#_4-외부-연동-팝빌-·-아임웹" aria-label="Permalink to &quot;4. 외부 연동 (팝빌 · 아임웹)&quot;">​</a></h2><p>본 모듈 활성 후 <strong>재무관리 → 외부 연동</strong> (<code>/app/finance/integrations</code>) 에서 자가 등록 가능.</p><table tabindex="0"><thead><tr><th>연동</th><th>용도</th><th>가이드</th></tr></thead><tbody><tr><td><strong>팝빌 — 전자세금계산서</strong></td><td>매출 확정 시 자동 발행 + 발행 결과 자동 갱신</td><td><a href="./finance-popbill.html">팝빌 연동</a></td></tr><tr><td><strong>팝빌 — 계좌조회 (EasyFin)</strong></td><td>사업자 계좌 입금내역 자동 수집 → 매출 자동 매칭</td><td><a href="./finance-popbill.html">팝빌 연동</a></td></tr><tr><td><strong>아임웹 OAuth2</strong></td><td>아임웹 주문 → billing_item 자동 매핑</td><td>(작성 예정)</td></tr></tbody></table><blockquote><p>자격증명은 모두 AES-GCM 으로 암호화 저장 — 시스템관리자도 평문 조회 불가.</p></blockquote><hr><h2 id="_5-세금계산서-청구-경비-—-기능-개요" tabindex="-1">5. 세금계산서 / 청구 / 경비 — 기능 개요 <a class="header-anchor" href="#_5-세금계산서-청구-경비-—-기능-개요" aria-label="Permalink to &quot;5. 세금계산서 / 청구 / 경비 — 기능 개요&quot;">​</a></h2><table tabindex="0"><thead><tr><th>영역</th><th>기능</th></tr></thead><tbody><tr><td><strong>매출 대장</strong></td><td>청구 건 생성 → 입금 매칭 → 세금계산서 발행까지 일원 추적</td></tr><tr><td><strong>입금 매칭</strong></td><td>팝빌 EasyFin 수집 → 입금자명/금액 자동 매칭 → 보류함에서 수동 선택 가능</td></tr><tr><td><strong>세금계산서</strong></td><td>입금 확정 시 자동 발행 (팝빌) / 수동 발행 / 수정 발행</td></tr><tr><td><strong>경비</strong></td><td>메일에서 영수증 첨부 → 경비 행 자동 생성 (<code>create_expense_from_email</code> 흐름)</td></tr><tr><td><strong>계약</strong></td><td>CRM 견적 승격 → 계약 행 / 매출 자동화 시작점</td></tr><tr><td><strong>정산 보고서</strong></td><td>월별 매출 vs 입금 vs 세금계산서 매칭 현황</td></tr></tbody></table><hr><h2 id="_6-알림-m5" tabindex="-1">6. 알림 (M5) <a class="header-anchor" href="#_6-알림-m5" aria-label="Permalink to &quot;6. 알림 (M5)&quot;">​</a></h2><p>다음 이벤트 발생 시 SSE / 모바일 푸시로 알림:</p><ul><li>입금 자동 매칭 성공 (담당자에게)</li><li>입금 매칭 보류함에 신규 항목</li><li>세금계산서 발행 완료 / 실패</li><li>아임웹 주문 신규 수집</li></ul><p>알림 수신자 / 채널 설정은 별도 정책 — 현재는 매출 담당 사용자 자동 구독.</p><hr><h2 id="_7-모듈-비활성화-시-영향" tabindex="-1">7. 모듈 비활성화 시 영향 <a class="header-anchor" href="#_7-모듈-비활성화-시-영향" aria-label="Permalink to &quot;7. 모듈 비활성화 시 영향&quot;">​</a></h2><table tabindex="0"><thead><tr><th>항목</th><th>영향</th></tr></thead><tbody><tr><td>좌측 사이드바 <strong>재무관리</strong> 메뉴</td><td>즉시 사라짐</td></tr><tr><td>매출 / 청구 / 경비 / 계약 데이터</td><td>DB 에 보관 (재활성 시 복구)</td></tr><tr><td>팝빌 / 아임웹 외부 연동 자격증명</td><td>보관됨 (재활성 시 복구) — 폴링 cron 만 중단</td></tr><tr><td>세금계산서 자동 발행 cron</td><td>중단</td></tr><tr><td>입금 자동 수집 cron</td><td>중단</td></tr><tr><td>CRM 견적 → 계약 승격</td><td>비활성</td></tr></tbody></table><p>자격증명까지 삭제하려면 외부 연동 화면에서 개별 [연결 해제] 후 모듈 비활성.</p><hr><h2 id="_8-트러블슈팅" tabindex="-1">8. 트러블슈팅 <a class="header-anchor" href="#_8-트러블슈팅" aria-label="Permalink to &quot;8. 트러블슈팅&quot;">​</a></h2><h3 id="메뉴가-안-보임" tabindex="-1">메뉴가 안 보임 <a class="header-anchor" href="#메뉴가-안-보임" aria-label="Permalink to &quot;메뉴가 안 보임&quot;">​</a></h3><ul><li>모듈 ON 확인</li><li>메뉴 노출 토글에서 그룹/개별 OFF 되어 있는지 확인 (3-2 참고)</li></ul><h3 id="세금계산서-자동-발행이-안-됨" tabindex="-1">세금계산서 자동 발행이 안 됨 <a class="header-anchor" href="#세금계산서-자동-발행이-안-됨" aria-label="Permalink to &quot;세금계산서 자동 발행이 안 됨&quot;">​</a></h3><ul><li>팝빌 연동 자격증명 등록 + 연결 테스트 성공 여부 확인</li><li>팝빌 측 공동인증서 등록 여부</li><li>팝빌 콘솔의 콜백 URL + 시스템 환경변수 <code>POPBILL_WEBHOOK_SECRET</code> (시스템관리자 영역)</li></ul><h3 id="입금이-자동-매칭-안-됨" tabindex="-1">입금이 자동 매칭 안 됨 <a class="header-anchor" href="#입금이-자동-매칭-안-됨" aria-label="Permalink to &quot;입금이 자동 매칭 안 됨&quot;">​</a></h3><ul><li>입금 매칭 보류함에 쌓이는지 확인 (매칭 후보가 여러 건이면 자동 매칭 보류)</li><li>alias 학습 (M4-A) 이 누적될수록 자동 매칭률 향상</li></ul><hr><h2 id="관련-가이드" tabindex="-1">관련 가이드 <a class="header-anchor" href="#관련-가이드" aria-label="Permalink to &quot;관련 가이드&quot;">​</a></h2><ul><li><a href="./finance-popbill.html">팝빌 연동</a> — 세금계산서 + 입금조회 자격증명 자가 등록</li><li><a href="./modules-crm.html">CRM 모듈 (관리자)</a> — 견적 → 계약 승격 흐름</li><li><a href="./modules-gmail.html">Gmail 모듈 (관리자)</a> — 메일 → 경비 (영수증 첨부) 흐름</li></ul>`,48)])])}const u=a(d,[["render",s]]);export{b as __pageData,u as default};
